/bin/zsh -lc "docker compose exec app node -e '
const net = require(\"net\");

const client = net.createConnection(9229, \"127.0.0.1\", () => {
  const req = \"GET /b08fadb0-00ad-4fb6-87dc-f42b904b89fa HTTP/1.1\\r\\n\" +
              \"Host: 127.0.0.1:9229\\r\\n\" +
              \"Upgrade: websocket\\r\\n\" +
              \"Connection: Upgrade\\r\\n\" +
              \"Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\\r\\n\" +
              \"Sec-WebSocket-Version: 13\\r\\n\\r\\n\";
  client.write(req);
});

let upgraded = false;
let buf = Buffer.alloc(0);

function sendWS(msg) {
  const payload = Buffer.from(msg);
  let header;
  if (payload.length < 126) {
    header = Buffer.from([0x81, 0x80 | payload.length, 0, 0, 0, 0]);
  } else {
    header = Buffer.alloc(8);
    header[0] = 0x81;
    header[1] = 0x80 | 126;
    header.writeUInt16BE(payload.length, 2);
    // mask 4 bytes are 0, so payload is unmasked
  }
  client.write(Buffer.concat([header, payload]));
}

client.on(\"data\", (data) => {
  buf = Buffer.concat([buf, data]);
  if ("'!upgraded) {
    const idx = buf.indexOf("'"\\r\\n\\r\\n\");
    if (idx "'!== -1) {
      upgraded = true;
      buf = buf.subarray(idx + 4);
      // Send evaluate command
      const cmd = JSON.stringify({
        id: 1,
        method: "Runtime.evaluate",
        params: {
          expression: "(() => { const v8 = require('"\\\"v8\\\"); return JSON.stringify({ mem: process.memoryUsage(), heap: v8.getHeapStatistics() }); })()\",
          returnByValue: true
        }
      });
      sendWS(cmd);
    }
  } else {
    // Parse WS frames
    while (buf.length >= 2) {
      const len1 = buf[1] & 0x7f;
      let offset = 2;
      let payloadLen = len1;
      if (len1 === 126) {
        if (buf.length < 4) break;
        payloadLen = buf.readUInt16BE(2);
        offset = 4;
      } else if (len1 === 127) {
        if (buf.length < 10) break;
        payloadLen = Number(buf.readBigUInt64BE(2));
        offset = 10;
      }
      if (buf.length < offset + payloadLen) break;
      const payload = buf.subarray(offset, offset + payloadLen);
      buf = buf.subarray(offset + payloadLen);
      console.log(payload.toString());
      process.exit(0);
    }
  }
});
'"

