      await checkLimits(accountId, amount);
      await client.query("UPDATE accounts SET balance = balance + $1 WHERE id = $2", [amount, accountId]);
    }
    await client.query("COMMIT");
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}

module.exports = { deposit };
EOF
"}

