const fs = require(\"fs\");
const file = \"src/services/catalog.js\";
let content = fs.readFileSync(file, \"utf8\");
const oldFn = "'`async function getItems(ids) {
  const items = [];
  for (const id of ids) {
    const { rows } = await pool.query("SELECT id, value, name FROM items WHERE id = $1", [id]);
    if (rows[0]) items.push(rows[0]);
  }
  return items;
}`;

const newFn = `async function getItems(ids) {
  if (!ids || ids.length === 0) return [];
  const { rows } = await pool.query(
    "SELECT id, value, name FROM items WHERE id = ANY($1::int[])",
    [ids]
  );
  const byId = new Map(rows.map((r) => [r.id, r]));
  const items = [];
  for (const id of ids) {
    const item = byId.get(id);
    if (item) items.push(item);
  }
  return items;
}`;

if (!content.includes(oldFn)) {
  console.error("Pattern not found");
  process.exit(1);
}
content = content.replace(oldFn, newFn);
fs.writeFileSync(file, content, "utf8");
console.log("Updated successfully");
'"'"

