  const q = new Queue(\"test-backoff\", { connection: conn });
  await q.add(\"test\", { foo: \"bar\" }, {
    attempts: 3,
    backoff: { type: \"custom\" }
  });

  const timestamps = [];
  const w = new Worker(\"test-backoff\", async (job) => {
    timestamps.push(Date.now());
    const err = new Error(\"rate limited\");
    err.retryAfterSec = 1;
    throw err;
  }, {
    connection: conn,
    settings: {
      backoffStrategy: (attemptsMade, type, err, job) => {
        console.log(\"custom backoffStrategy called:\", { attemptsMade, type, errMsg: err && err.message });
        return 1000;
      }
    }
  });

  await new Promise(r => setTimeout(r, 2500));
