{"cmd":"docker compose exec app node -e '
const { Queue, Worker } = require("bullmq");
const IORedis = require("ioredis");
const conn = new IORedis("redis://redis:6379", { maxRetriesPerRequest: null });

async function run() {
  const q = new Queue("test-limiter", { connection: conn });
  for (let i = 0; i < 10; i++) {
    await q.add("test", { i });
  }
  const timestamps = [];
  const w = new Worker("test-limiter", async (job) => {
    timestamps.push(Date.now());
  }, {
    connection: conn,
    concurrency: 5,
    limiter: { max: 5, duration: 1000 }
  });

  await new Promise(r => setTimeout(r, 2500));
  await w.close();
  await q.obliterate({ force: true });
  await conn.quit();

  console.log("Processed:", timestamps.length);
  for (let i = 1; i < timestamps.length; i++) {
    console.log(`diff ${i-1}->${i}:`, timestamps[i] - timestamps[i-1], "ms");
  }
}
run();
'"}

